import zipfile,re,glob,os,collections,html
patterns={
 'practice':re.compile(r'Funds\s*(?:&|and)\s*Asset\s*Management',re.I),
 'lpac':re.compile(r'LPAC|LP\s+advisory\s+committee|LP\s+Advisory\s+Committee|limited\s+partner\s+advisory\s+committee|advisory\s+committee',re.I),
 'lpa':re.compile(r'limited partnership agreement|\bLPA\b',re.I),
 'signed':re.compile(r'signed|executed|execution version|fully executed|not signed|unsigned|never signed',re.I),
}
D=collections.defaultdict(lambda:collections.defaultdict(list))
for p in glob.glob('documents/matters/**/*.docx',recursive=True):
    m=re.search(r'documents/matters/([^/]+)/',p)
    if not m: continue
    mid=m.group(1)
    try:
      with zipfile.ZipFile(p) as z: xml=z.read('word/document.xml').decode('utf8','ignore')
      txt=' '.join(re.findall(r'<w:t[^>]*>(.*?)</w:t>',xml))
      txt=html.unescape(txt)
      for k,pat in patterns.items():
        if pat.search(txt): D[mid][k].append(p)
    except: pass
for mid in sorted(D):
    if D[mid]['practice'] or (D[mid]['lpac'] and D[mid]['lpa']):
      print('\n'+mid)
      for k in patterns:
        if D[mid][k]:
          print(' ',k,len(D[mid][k]))
          for p in D[mid][k][:8]: print('   ',p)
PY","description":"Aggregate matters with funds and LPAC indicators","timeoutMs":200000}

